import{_ as a,o as e,c as o,ag as r}from"./chunks/framework.CAXxHpAX.js";const q=JSON.parse('{"title":"家庭道场","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-家庭道场.md","filePath":"50-概念资料/dict-家庭道场.md","lastUpdated":1778155802000}'),l={name:"50-概念资料/dict-家庭道场.md"};function d(i,t,h,c,n,u){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="家庭道场" tabindex="-1">家庭道场 <a class="header-anchor" href="#家庭道场" aria-label="Permalink to &quot;家庭道场&quot;">​</a></h1><blockquote><p>传统：儒家（齐家）| 佛家对应：在家修行 | 道家对应：和光同尘</p></blockquote><h2 id="了空居士的定义" tabindex="-1">了空居士的定义 <a class="header-anchor" href="#了空居士的定义" aria-label="Permalink to &quot;了空居士的定义&quot;">​</a></h2><p>&quot;家庭道场&quot;就是了空居士对<strong>家庭即修行现场</strong>的核心观点。家庭不是修行的障碍，而是最好的修行场所——因为家人是你最亲近的人，也是最容易触发你情绪的人。在家里磨出来的功夫，是真的功夫。</p><p>关键操作：在家庭关系中保持<strong>柔软</strong>——&quot;石头和石头之间不填上水泥浆，那个石头永远是摆不平的。&quot; 家庭中需要有一个人先软下来，不是软弱，是智慧。了空居士特别指出男人的责任——在家庭关系中主动表达温情、主动化解矛盾。</p><h2 id="原话出处" tabindex="-1">原话出处 <a class="header-anchor" href="#原话出处" aria-label="Permalink to &quot;原话出处&quot;">​</a></h2><blockquote><p>&quot;家庭是道场，工作单位是道场，社会是道场。&quot; — <a href="/60-原文段落/金刚经1分-修行在生活中">金刚经1分-修行在生活中</a></p></blockquote><blockquote><p>&quot;家庭里面最重要还是我们男人。如果妻子不开心，你拉拉手摇摇肩膀都可以。两个人都是硬邦邦的，永远摆不平的。&quot; — 修行入世（20090112b）</p></blockquote><h2 id="常见误解" tabindex="-1">常见误解 <a class="header-anchor" href="#常见误解" aria-label="Permalink to &quot;常见误解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>正解</th></tr></thead><tbody><tr><td>修行就要离家、不理家务</td><td>家庭正是最好的修行场所</td></tr><tr><td>家庭矛盾是修行的障碍</td><td>家庭矛盾正是历境炼心的材料</td></tr></tbody></table><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-处世">dict-处世</a> — 家庭是处世的第一现场</li><li><a href="/50-概念资料/dict-敬">dict-敬</a> — 对家人的恭敬比对陌生人更难，也更重要</li><li><a href="/50-概念资料/dict-柔弱">dict-柔弱</a> — 家庭中先软下来的人真正有力量</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-历境炼心">model-历境炼心</a> — 家庭是最直接的历境炼心现场</li><li><a href="/10-核心模型/model-圆融中和">model-圆融中和</a> — 在家庭关系中走中道，不冷暴力也不过度纵容</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><p>在家里，当情绪起来时，先停三秒，深呼吸——这就是在家里的&quot;静坐&quot;。主动表达温情，不把家人的好视为理所当然。</p>',16)])])}const b=a(l,[["render",d]]);export{q as __pageData,b as default};
